open(lib_path,'w').write('''def panels(grid, sep):
    """The two subgrids on either side of column sep."""
    return [r[:sep] for r in grid], [r[sep + 1:] for r in grid]

def shared_color(a, b):
    """The single color present in both grids."""
    sa = {v for row in a for v in row}; sb = {v for row in b for v in row}
    return (sa & sb).pop()

def overlay_match(a, b, yes=3):
    """Same size as a: yes where a and b agree cellwise, otherwise the color they share."""
    s = shared_color(a, b)
    return [[yes if x == y else s for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]

def split_overlay(grid, sep, yes=3):
    """Match-overlay of the two panels on either side of column sep."""
    a, b = panels(grid, sep)
    return overlay_match(a, b, yes)
